-- Native container72 parts share the size-specific store, isolated from 64px edits.
ALTER TABLE reference_part_sizes RENAME TO reference_part_sizes_old;
CREATE TABLE reference_part_sizes (
    reference_id TEXT NOT NULL REFERENCES "references"(reference_id),
    role TEXT NOT NULL CHECK(role IN ('main', 'sub', 'container', 'symbol')),
    size INTEGER NOT NULL CHECK(size = 72),
    icon TEXT, layout TEXT, built_sha TEXT, updated_at TEXT, updated_by TEXT,
    PRIMARY KEY(reference_id, role, size));
INSERT INTO reference_part_sizes SELECT * FROM reference_part_sizes_old;
DROP TABLE reference_part_sizes_old;
CREATE INDEX reference_part_sizes_icon ON reference_part_sizes(icon);
